package main

import (
	"errors"
	"testing"
	"time"
)

// TestStoreExpiryBoundary checks that a session still inside the TTL stays
// readable and one past the TTL is dropped, using the fake clock so the test
// never sleeps.
func TestStoreExpiryBoundary(t *testing.T) {
	t.Helper()
	cases := []clockCase{
		{
			name: "under ttl stays",
			steps: []clockStep{
				{at: 0, act: func(s *Store) { s.Create("alice", "Alice") }},
				{at: 1, act: func(s *Store) { s.Get("alice") }},
			},
			wantLen: 1,
		},
		{
			name: "over ttl dropped",
			steps: []clockStep{
				{at: 0, act: func(s *Store) { s.Create("bob", "Bob") }},
				{at: 2, act: func(s *Store) {
					if _, err := s.Get("bob"); !errors.Is(err, ErrNotFound) {
						t.Errorf("Get(bob) err = %v, want %v", err, ErrNotFound)
					}
				}},
			},
			wantLen: 0,
		},
	}
	runClockTable(t, cases)
}

